__global__ void exclusive_cumsum_kernel(const float* input, float* output, int num_rows, int row_len) {
    int row_id = blockIdx.x * blockDim.x + threadIdx.x;
    if (row_id >= num_rows) return;
    float sum = 0.0f;
    for (int col = 0; col < row_len; ++col) {
        sum += input[row_id * row_len + col];
        output[row_id * row_len + col] = sum;
    }
}
